// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

// Material tidak terikat mesin, jadi field mesin dan gramasi disembunyikan
function aturKonsepJenis() {
    const isMaterial = $('#jenis').val() === '1';

    $('.group-mesin').toggle(!isMaterial);

    if (isMaterial) {
        $('#mesin_tipe_id').val('');
        $('#gsm').val('0');
    }
}

// DataTables
$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${urlThis}/tabel`,
            type: 'POST',
            data: function (d) {
                d.filter_jenis = $('#filter_jenis').val();
                d.filter_tipe = $('#filter_tipe').val();
            }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            { text: 'Add', action: () => simpan() },
            {
                text: 'Reload',
                action: function (e, dt) {
                    dt.search('').draw();
                    $('#filter_jenis, #filter_tipe').val('').trigger('change');
                    Swal.fire({ icon: 'success', title: 'Informasi', text: 'Selesai reload tabel ke kondisi awal', showConfirmButton: false, timer: 1300 })
                        .then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 7], className: 'dt-body-center' },
            { targets: 5, className: 'dt-body-right' },
            { targets: 7, orderable: false },
            { targets: [8, 9], render: function (data, type, row) { return CirebonwebFormat.Tanggal(data) } }
        ]
    });

    $('#tabelData_filter.dataTables_filter').append($('#filter_jenis, #filter_tipe'));
    $(document).on('change', '#filter_jenis, #filter_tipe', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    $(document).on('change', '#jenis', aturKonsepJenis);

    // Reset Modal
    $modalDiv
        .on('shown.bs.modal', function () {
            aturKonsepJenis();
            formCek.resetInitial();
        })
        .on('hidden.bs.modal', function () {
            CirebonwebForm.FormReset(this);
            aturKonsepJenis();
        });
});

// Form Submit (Insert/Update)
function simpan(id) {
    const $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${urlThis}/simpan`;

    if (id > 0) {
        CirebonwebForm.FormFetch(`${urlThis}/getid`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            $modalTitle.text('Edit Data');
            $btnSubmit.text('Update');
            $formData.find('#id').val(response.data.id);
            $formData.find('#jenis').val(response.data.jenis || 0);
            $formData.find('#kode').val(response.data.kode);
            $formData.find('#nama').val(response.data.nama);
            $formData.find('#gsm').val(response.data.gsm);
            $formData.find('#rumus').val(response.data.rumus || 0);
            $formData.find('#mesin_tipe_id').val(response.data.mesin_tipe_id || '');
            $modalDiv.modal('show');
        });
    } else {
        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            jenis: { required: true, digits: true },
            kode: { required: true, minlength: 2, maxlength: 20 },
            nama: { required: true, minlength: 3, maxlength: 100 },
            gsm: { digits: true, maxlength: 4 },
            rumus: { required: true, digits: true },
        },
        submitHandler: function () {
            if (!formCek.isChanged()) return false;
            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;
                    $btnSubmit.attr('disabled', true).html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () { $btnSubmit.attr('disabled', false).html('Simpan'); }
            }).done(function (response) {
                if (!response.success) return;
                $modalDiv.modal('hide');
                Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                    .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
            });
            return false;
        }
    }));
}

// Form Submit (Delete)
function hapus(id) {
    Swal.fire({
        title: 'Konfirmasi',
        html: 'Apakah yakin ingin menghapus data ini? <br> Data akan dihapus secara permanen!',
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Ya, hapus!'
    }).then(function (result) {
        if (!result.isConfirmed) return;
        CirebonwebForm.FormFetch(`${urlThis}/hapus`, { id }, 'POST', {}).done(function (response) {
            if (!response.success) return;
            Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                .then(function () { $tabelData.DataTable().ajax.reload(null, false); });
        });
    });
}
